#include <sched.h>
#include <signal.h>
#include <sys/mount.h>
#include <sys/syscall.h>
#include <sys/wait.h>
#include <unistd.h>
#include <cstdio>
int main(){
  long pid = syscall(SYS_clone, CLONE_NEWUSER | SIGCHLD, 0, 0, 0, 0);
  if (pid == 0) _exit(0);
  if (pid > 0) waitpid(pid, nullptr, 0);
  std::puts(pid < 0 ? "clone blocked" : "clone CREATED A USER NAMESPACE");
  std::puts(unshare(CLONE_NEWUSER) < 0 ? "unshare blocked" : "unshare CREATED A USER NAMESPACE");
  std::puts(mount("none", "/box", "tmpfs", 0, nullptr) < 0 ? "mount blocked" : "mount SUCCEEDED");
  pid_t child = fork();
  if (child == 0) _exit(0);
  if (child > 0) waitpid(child, nullptr, 0);
  std::puts(child > 0 ? "fork works" : "fork BROKEN");
}
